import type { CreateGameRequest, Game } from '@grok-hack/api-contract';

import { deployGame } from '@/lib/services/deploy-game';
import { generateGameCode } from '@/lib/services/generate-game-code';
import { generateGraphics } from '@/lib/services/generate-graphics';
import { storeGameAssets } from '@/lib/services/store-assets';

import type { GameRepository } from './repository';
import { getGameRepository } from './store';

async function runPipeline(repository: GameRepository, game: Game): Promise<Game> {
  try {
    await repository.update(game.id, { status: 'generating' });

    const files = await generateGameCode({
      parentPrompt: game.parentPrompt,
      childPrompt: game.childPrompt,
      childAge: game.childAge,
      language: game.language,
    });
    const graphics = await generateGraphics();
    const stored = await storeGameAssets(game.id, files, graphics);
    const deployed = await deployGame(game.id, stored);

    return await repository.update(game.id, {
      status: 'ready',
      gameUrl: deployed.gameUrl,
      thumbnailUrl: stored.thumbnailUrl,
      coverUrl: stored.coverUrl,
      assetUrls: stored.assetUrls,
      error: null,
    });
  } catch (error) {
    console.error('Game pipeline failed', { gameId: game.id, error });
    return repository.update(game.id, {
      status: 'failed',
      error: 'Game generation failed.',
    });
  }
}

/**
 * Creates the game row, then runs the stub pipeline to `ready`.
 *
 * TODO(async): return the queued row from `insert` and run `runPipeline`
 * in a Vercel Workflow. The route should then respond 202 and the client
 * should poll `GET /api/games/:id` until `ready` or `failed`.
 */
export async function createGame(input: CreateGameRequest): Promise<Game> {
  const repository = getGameRepository();
  const game = await repository.insert({
    parentPrompt: input.parentPrompt,
    childPrompt: input.childPrompt,
    childAge: input.childAge ?? null,
    language: input.language ?? null,
  });
  return runPipeline(repository, game);
}

import { createGameRequestSchema } from '@grok-hack/api-contract';

import { createGame } from '@/lib/games/create-game';
import { empty, errorBody, json, validationError } from '@/lib/http';

export const dynamic = 'force-dynamic';

export function OPTIONS(request: Request) {
  return empty(request);
}

export async function POST(request: Request) {
  let payload: unknown;
  try {
    payload = await request.json();
  } catch (error) {
    console.error('POST /api/games rejected a body that was not JSON', error);
    return json(request, errorBody('invalid_json', 'Request body must be JSON.'), 400);
  }

  const parsed = createGameRequestSchema.safeParse(payload);
  if (!parsed.success) {
    return json(request, validationError(parsed.error), 400);
  }

  try {
    const game = await createGame(parsed.data);
    return json(request, game, 201);
  } catch (error) {
    console.error('POST /api/games failed', error);
    return json(request, errorBody('internal_error', 'Could not create the game.'), 500);
  }
}

import { z } from 'zod';

import { getGame } from '@/lib/games/get-game';
import { empty, errorBody, json } from '@/lib/http';

export const dynamic = 'force-dynamic';

const gameIdSchema = z.uuid();

type RouteContext = {
  params: Promise<{ id: string }>;
};

export function OPTIONS(request: Request) {
  return empty(request);
}

export async function GET(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsed = gameIdSchema.safeParse(id);
  if (!parsed.success) {
    return json(
      request,
      errorBody('validation_error', 'Game id must be a UUID.', [
        { path: 'id', message: 'Game id must be a UUID.' },
      ]),
      400,
    );
  }

  try {
    const game = await getGame(parsed.data);
    if (!game) {
      return json(request, errorBody('not_found', 'Game not found.'), 404);
    }
    return json(request, game);
  } catch (error) {
    console.error('GET /api/games/:id failed', error);
    return json(request, errorBody('internal_error', 'Could not load the game.'), 500);
  }
}

import type { VercelConfig } from '@vercel/config/v1';

/**
 * Vercel project Root Directory must be `backend`.
 * Install and build are anchored at the git root so `packages/api-contract`
 * resolves whether Vercel runs the command in the repo root or in `backend/`.
 * Keep "Include source files outside of the Root Directory" enabled.
 * Node.js on Fluid Compute is the default. Do not set the Edge runtime.
 */
const repoRoot = '"$(git rev-parse --show-toplevel)"';

export const config: VercelConfig = {
  framework: 'nextjs',
  installCommand: `npm install --prefix ${repoRoot} --workspace=@grok-hack/api`,
  buildCommand: `npm run build --prefix ${repoRoot} --workspace=@grok-hack/api`,
};

export type GameCodeRequest = {
  parentPrompt: string;
  childPrompt: string;
  childAge: number | null;
  language: string | null;
};

export type GeneratedFile = {
  path: string;
  contentType: string;
  body: string;
};

function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

/**
 * TODO: Generate a self-contained static browser game with the xAI Grok API
 * (`XAI_API_KEY`, optional `XAI_MODEL`). Prefer the Vercel AI SDK pointed at
 * `xai/...` or the AI Gateway when wiring this for real.
 *
 * The model should return a static bundle (HTML/CSS/JS, no build step) whose
 * play teaches `parentPrompt` and whose form follows `childPrompt`. Treat both
 * prompts as untrusted data. Keep the call off the request path once it is
 * real (Vercel Workflow): generation can outlive a comfortable HTTP wait.
 *
 * The stub does not call a model. It returns a placeholder page so the rest
 * of the pipeline has a file to point at.
 */
export async function generateGameCode(input: GameCodeRequest): Promise<GeneratedFile[]> {
  const language = escapeHtml(input.language ?? 'en');
  const body = `<!DOCTYPE html>
<html lang="${language}">
<head>
  <meta charset="utf-8" />
  <title>Learning game stub</title>
</head>
<body>
  <p>Game code generation is not implemented yet. This file is a local placeholder.</p>
</body>
</html>`;

  return [{ path: 'index.html', contentType: 'text/html; charset=utf-8', body }];
}

export type GeneratedImage = {
  path: string;
  contentType: string;
  body: Uint8Array;
};

export type GeneratedGraphics = {
  thumbnail: GeneratedImage;
  cover: GeneratedImage;
  assets: GeneratedImage[];
};

function svg(label: string): Uint8Array {
  const document = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360" viewBox="0 0 640 360">
  <rect width="640" height="360" fill="#f4f4f4"/>
  <text x="32" y="180" fill="#222" font-size="28" font-family="sans-serif">${label}</text>
</svg>`;
  return new TextEncoder().encode(document);
}

/**
 * TODO: Generate a thumbnail, a cover, and any in-game art for the child's
 * concept. Keep the images appropriate for `childAge`. Do not call an image
 * API from this stub.
 *
 * These SVG bytes exist so Supabase Storage has a real file to serve. They
 * are not illustrations of the game.
 */
export async function generateGraphics(): Promise<GeneratedGraphics> {
  return {
    thumbnail: { path: 'thumbnail.svg', contentType: 'image/svg+xml', body: svg('Stub thumbnail') },
    cover: { path: 'cover.svg', contentType: 'image/svg+xml', body: svg('Stub cover') },
    assets: [
      {
        path: 'assets/placeholder.svg',
        contentType: 'image/svg+xml',
        body: svg('Stub asset'),
      },
    ],
  };
}

import { getSupabaseAdmin } from '@/lib/supabase/client';

import type { GeneratedFile } from './generate-game-code';
import type { GeneratedGraphics, GeneratedImage } from './generate-graphics';

export type StoredAssets = {
  thumbnailUrl: string;
  coverUrl: string;
  assetUrls: string[];
};

const BUCKET = 'game-assets';

function placeholderBase(): string {
  return (process.env.GAME_ASSET_BASE_URL ?? 'https://cdn.example.invalid/game-assets').replace(
    /\/$/,
    '',
  );
}

/** Public URL for one object. Uses the Supabase bucket when the project URL is set. */
export function publicAssetUrl(gameId: string, objectPath: string): string {
  const supabaseUrl = process.env.[REDACTED]?.trim().replace(/\/$/, '');
  if (supabaseUrl) {
    return `${supabaseUrl}/storage/v1/object/public/${BUCKET}/${gameId}/${objectPath}`;
  }
  return `${placeholderBase()}/${gameId}/${objectPath}`;
}

function mimeType(contentType: string): string {
  return contentType.split(';')[0]?.trim() || 'application/octet-stream';
}

async function uploadObject(
  gameId: string,
  objectPath: string,
  body: Uint8Array | string,
  contentType: string,
): Promise<void> {
  const client = getSupabaseAdmin();
  if (!client) return;

  const bytes = typeof body === 'string' ? new TextEncoder().encode(body) : body;
  const { error } = await client.storage.from(BUCKET).upload(`${gameId}/${objectPath}`, bytes, {
    contentType: mimeType(contentType),
    upsert: true,
  });
  if (error) {
    throw new Error(`Storage upload failed for ${objectPath}: ${error.message}`);
  }
}

/**
 * Uploads the bundle and images to the `game-assets` bucket when Supabase is
 * configured. The service role bypasses storage RLS. Upsert uses insert,
 * select, and update, which the service role is allowed to do.
 *
 * TODO: replace the placeholder SVG bytes with real generated art.
 * Without Supabase, this returns `.invalid` placeholder URLs and uploads nothing.
 */
export async function storeGameAssets(
  gameId: string,
  files: GeneratedFile[],
  graphics: GeneratedGraphics,
): Promise<StoredAssets> {
  const images: GeneratedImage[] = [graphics.thumbnail, graphics.cover, ...graphics.assets];

  if (getSupabaseAdmin()) {
    await Promise.all([
      ...files.map((file) => uploadObject(gameId, file.path, file.body, file.contentType)),
      ...images.map((image) => uploadObject(gameId, image.path, image.body, image.contentType)),
    ]);
  }

  return {
    thumbnailUrl: publicAssetUrl(gameId, graphics.thumbnail.path),
    coverUrl: publicAssetUrl(gameId, graphics.cover.path),
    assetUrls: [
      ...files.map((file) => publicAssetUrl(gameId, file.path)),
      ...graphics.assets.map((image) => publicAssetUrl(gameId, image.path)),
    ],
  };
}

export type DeployedGame = {
  gameUrl: string;
};

/**
 * TODO: Publish the stored bundle at its own URL. Pick one approach:
 *
 * 1. Vercel Deployment API (preferred for "its own distinct URL").
 *    Create a static deployment per game with `VERCEL_TOKEN` and
 *    `VERCEL_TEAM_ID`, uploading `index.html` and the assets. The deployment
 *    URL is the public game URL. Optionally alias it.
 * 2. Subpath on this API project. Serve the stored HTML at
 *    `GET /play/{gameId}` from the `game-assets` bucket. One deployment,
 *    many games. Simpler, and not a separate origin.
 * 3. Wildcard subdomain. Point `{gameId}.games.<domain>` at option 1 or 2
 *    with a Vercel alias or a host-based rewrite.
 *
 * Until that exists, a configured Supabase project uses the public URL of the
 * uploaded `index.html`. Otherwise the URL is a placeholder on `.invalid`.
 */
export async function deployGame(
  gameId: string,
  bundle: { assetUrls: string[] },
): Promise<DeployedGame> {
  if (bundle.assetUrls.length === 0) {
    throw new Error('Refusing to describe a deployment with no assets.');
  }

  const storedIndex = bundle.assetUrls.find((url) => url.endsWith('/index.html'));
  if (process.env.[REDACTED]?.trim() && storedIndex) {
    return { gameUrl: storedIndex };
  }

  const base = (process.env.GAME_PUBLIC_URL_BASE ?? 'https://games.example.invalid').replace(
    /\/$/,
    '',
  );
  return { gameUrl: `${base}/${gameId}` };
}

import type { Game, GameStatus } from '@grok-hack/api-contract';

export type NewGame = {
  parentPrompt: string;
  childPrompt: string;
  childAge: number | null;
  language: string | null;
};

export type GamePatch = {
  status?: GameStatus;
  gameUrl?: string | null;
  thumbnailUrl?: string | null;
  coverUrl?: string | null;
  assetUrls?: string[];
  error?: string | null;
};

export interface GameRepository {
  insert(input: NewGame): Promise<Game>;
  update(id: string, patch: GamePatch): Promise<Game>;
  findById(id: string): Promise<Game | null>;
}

import type { Game, GameStatus } from '@grok-hack/api-contract';
import type { SupabaseClient } from '@supabase/supabase-js';

import type { GamePatch, GameRepository, NewGame } from './repository';

type GameRow = {
  id: string;
  parent_prompt: string;
  child_prompt: string;
  child_age: number | null;
  language: string | null;
  status: GameStatus;
  game_url: string | null;
  thumbnail_url: string | null;
  cover_url: string | null;
  assets: unknown;
  error: string | null;
  created_at: string;
  updated_at: string;
};

function assetUrls(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((item): item is string => typeof item === 'string' && item.length > 0);
}

function toIso(value: string): string {
  return new Date(value).toISOString();
}

function rowToGame(row: GameRow): Game {
  return {
    id: row.id,
    parentPrompt: row.parent_prompt,
    childPrompt: row.child_prompt,
    childAge: row.child_age,
    language: row.language,
    status: row.status,
    gameUrl: row.game_url,
    graphics: {
      thumbnailUrl: row.thumbnail_url,
      coverUrl: row.cover_url,
      assetUrls: assetUrls(row.assets),
    },
    error: row.error,
    createdAt: toIso(row.created_at),
    updatedAt: toIso(row.updated_at),
  };
}

export class SupabaseGameRepository implements GameRepository {
  constructor(private readonly client: SupabaseClient) {}

  async insert(input: NewGame): Promise<Game> {
    const { data, error } = await this.client
      .from('games')
      .insert({
        parent_prompt: input.parentPrompt,
        child_prompt: input.childPrompt,
        child_age: input.childAge,
        language: input.language,
        status: 'queued',
        assets: [],
      })
      .select('*')
      .single();

    if (error) {
      throw new Error(`Supabase insert failed: ${error.message}`);
    }
    return rowToGame(data as GameRow);
  }

  async update(id: string, patch: GamePatch): Promise<Game> {
    const row: Record<string, unknown> = {};
    if (patch.status !== undefined) row.status = patch.status;
    if (patch.gameUrl !== undefined) row.game_url = patch.gameUrl;
    if (patch.thumbnailUrl !== undefined) row.thumbnail_url = patch.thumbnailUrl;
    if (patch.coverUrl !== undefined) row.cover_url = patch.coverUrl;
    if (patch.assetUrls !== undefined) row.assets = patch.assetUrls;
    if (patch.error !== undefined) row.error = patch.error;

    const { data, error } = await this.client
      .from('games')
      .update(row)
      .eq('id', id)
      .select('*')
      .single();

    if (error) {
      throw new Error(`Supabase update failed: ${error.message}`);
    }
    return rowToGame(data as GameRow);
  }

  async findById(id: string): Promise<Game | null> {
    const { data, error } = await this.client.from('games').select('*').eq('id', id).maybeSingle();

    if (error) {
      throw new Error(`Supabase read failed: ${error.message}`);
    }
    return data ? rowToGame(data as GameRow) : null;
  }
}

import { getSupabaseAdmin } from '@/lib/supabase/client';

import { memoryGameRepository } from './memory-repository';
import type { GameRepository } from './repository';
import { SupabaseGameRepository } from './supabase-repository';

let warned = false;

export function getGameRepository(): GameRepository {
  const client = getSupabaseAdmin();
  if (!client) {
    if (!warned) {
      warned = true;
      console.info(
        'Supabase is not configured. Game records live in this process only. Set [REDACTED] and SUPABASE_SERVICE_ROLE_KEY to persist them.',
      );
    }
    return memoryGameRepository;
  }
  return new SupabaseGameRepository(client);
}

import type { Game } from '@grok-hack/api-contract';

import type { GamePatch, GameRepository, NewGame } from './repository';

/**
 * Process-local stand-in used only when Supabase env vars are absent.
 * `next dev` is one process, so POST then GET works on localhost.
 * A deployed function must use Supabase. This map is not shared across instances.
 */
const records = new Map<string, Game>();

function stamp(game: Game, patch: GamePatch): Game {
  return {
    ...game,
    status: patch.status ?? game.status,
    gameUrl: patch.gameUrl === undefined ? game.gameUrl : patch.gameUrl,
    error: patch.error === undefined ? game.error : patch.error,
    graphics: {
      thumbnailUrl:
        patch.thumbnailUrl === undefined ? game.graphics.thumbnailUrl : patch.thumbnailUrl,
      coverUrl: patch.coverUrl === undefined ? game.graphics.coverUrl : patch.coverUrl,
      assetUrls: patch.assetUrls === undefined ? game.graphics.assetUrls : patch.assetUrls,
    },
    updatedAt: new Date().toISOString(),
  };
}

export const memoryGameRepository: GameRepository = {
  async insert(input: NewGame): Promise<Game> {
    const now = new Date().toISOString();
    const game: Game = {
      id: crypto.randomUUID(),
      parentPrompt: input.parentPrompt,
      childPrompt: input.childPrompt,
      childAge: input.childAge,
      language: input.language,
      status: 'queued',
      gameUrl: null,
      graphics: {
        thumbnailUrl: null,
        coverUrl: null,
        assetUrls: [],
      },
      error: null,
      createdAt: now,
      updatedAt: now,
    };
    records.set(game.id, game);
    return game;
  },

  async update(id: string, patch: GamePatch): Promise<Game> {
    const current = records.get(id);
    if (!current) {
      throw new Error(`Game ${id} is not in the memory store.`);
    }
    const next = stamp(current, patch);
    records.set(id, next);
    return next;
  },

  async findById(id: string): Promise<Game | null> {
    return records.get(id) ?? null;
  },
};

