        var button = scene.add
          .rectangle(480, y, 840, 66, 0xffffff, 0.96)
          .setStrokeStyle(4, hex(current.theme.palette.accent))
          .setDepth(8)
          .setInteractive({ useHandCursor: true });
        scene.add
          .text(480, y, index + 1 + '. ' + choice, {
            fontFamily: FONT,
            fontSize: size,
            color: '#102027',
