+import puppeteer from 'puppeteer-core';
+
+const runtime = readFileSync('/agent/repos/grok-hack-wro/backend/public/phaser/runtime.js');
+const files = {
+  '/runner-character.jpg': readFileSync('/tmp/live-games/runner-character.jpg'),
+  '/runner-background.jpg': readFileSync('/tmp/live-games/runner-background.jpg'),
+  '/runner-item.jpg': readFileSync('/tmp/live-games/runner-item.jpg'),
+  '/collect-character.jpg': readFileSync('/tmp/live-games/collect-character.jpg'),
+  '/collect-background.jpg': readFileSync('/tmp/live-games/collect-background.jpg'),
+  '/collect-item.jpg': readFileSync('/tmp/live-games/collect-item.jpg'),
+};
+
+function page(name) {
+  const spec = JSON.parse(readFileSync(`/tmp/live-games/${name}-spec.json`, 'utf8'));
+  spec.assets.characterUrl = `/${name}-character.jpg`;
+  spec.assets.backgroundUrl = `/${name}-background.jpg`;
+  spec.assets.itemUrl = `/${name}-item.jpg`;
+  spec.resultsUrl = '';
+  const json = JSON.stringify(spec).replaceAll('<', '\\u003c');
+  return `<!DOCTYPE html><html><head><meta charset="utf-8"><style>html,body{margin:0;height:100%;background:#111}#game{width:100%;height:100%}</style></head>
+<body><div id="game"></div>
+<script id="game-spec" type="application/json">${json}</script>
+<script src="https://cdn.jsdelivr.net/npm/phaser@3.90.0/dist/phaser.min.js"></script>
+<script src="/phaser/runtime.js"></script></body></html>`;
+}
+
+const pages = { '/runner.html': page('runner'), '/collect.html': page('collect') };
+const server = createServer((req, res) => {
+  const url = req.url.split('?')[0];
+  if (url === '/phaser/runtime.js') {
+    res.writeHead(200, { 'content-type': 'text/javascript' });
+    res.end(runtime);
+    return;
+  }
+  if (files[url]) {
+    res.writeHead(200, { 'content-type': 'image/jpeg' });
+    res.end(files[url]);
+    return;
+  }
+  if (pages[url]) {
+    res.writeHead(200, { 'content-type': 'text/html' });
+    res.end(pages[url]);
+    return;
+  }
+  res.writeHead(404);
+  res.end('no');
+});
+await new Promise((resolve) => server.listen(3012, '127.0.0.1', resolve));
+
+const browser = await puppeteer.launch({
+  executablePath: '/usr/bin/google-chrome',
+  headless: true,
+  args: ['--no-sandbox', '--disable-dev-shm-usage'],
+});
+for (const name of ['runner', 'collect']) {
+  const page = await browser.newPage();
+  await page.setViewport({ width: 1280, height: 800 });
+  await page.goto(`http://127.0.0.1:3012/${name}.html`, { waitUntil: 'networkidle0' });
+  await page.waitForFunction(() => document.documentElement.dataset.gameReady === '1');
+  await new Promise((r) => setTimeout(r, 1200));
+  const measured = await page.evaluate(() => window.__EDUBOT_STATE);
+  console.log(name, JSON.stringify({
+    scene: measured.scene,
+    score: measured.score,
+    index: measured.index,
+    prompt: measured.prompt,
+    banner: measured.banner,
+    player: measured.player,
+  }));
+  if (measured.score !== 0 || measured.index !== 0 || measured.banner) {
+    throw new Error(name + ' auto-played');
+  }
+  if (!measured.player || measured.player.displayWidth > 100) {
+    throw new Error(name + ' sprite still huge');
+  }
+  await page.screenshot({ path: `/opt/cursor/artifacts/fixed-${name}.png` });
+  await page.close();
+}
+await browser.close();
+server.close();
+console.log('live images ok');

